import{_ as a,o as t,c as n,a0 as i}from"./chunks/framework.DzvPB4Y-.js";const u=JSON.parse('{"title":"3D Packing · BPP3D","description":"","frontmatter":{},"headers":[],"relativePath":"frameworks/bpp3d/index.md","filePath":"frameworks/bpp3d/index.md"}'),o={name:"frameworks/bpp3d/index.md"};function r(d,e,s,l,c,p){return t(),n("div",null,[...e[0]||(e[0]=[i('<h1 id="_3d-packing-·-bpp3d" tabindex="-1">3D Packing · BPP3D <a class="header-anchor" href="#_3d-packing-·-bpp3d" aria-label="Permalink to &quot;3D Packing · BPP3D&quot;">​</a></h1><p>Cargo has three dimensions and weight. Choose container types, orientations and positions, then produce a checkable, renderable loading plan. The first lesson uses cuboids rather than cylinders or complex support rules.</p><h2 id="minimum-vocabulary" tabindex="-1">Minimum Vocabulary <a class="header-anchor" href="#minimum-vocabulary" aria-label="Permalink to &quot;Minimum Vocabulary&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Concept</th><th>API</th><th>Input or output</th></tr></thead><tbody><tr><td>Cargo and package</td><td><code>Item</code> / <code>Package</code></td><td>Dimensions, weight, materials and allowed orientations</td></tr><tr><td>Container type</td><td><code>BinType</code></td><td>Geometry, load capacity and type identity</td></tr><tr><td>Candidate container layer</td><td><code>BinLayer</code></td><td>Container type, demand coverage and placement traces</td></tr><tr><td>Application service</td><td><code>ColumnGenerationApplicationService</code></td><td>Master solves, generation, final selection and packing analysis</td></tr><tr><td>Final validation</td><td><code>PackingGeometryGuard</code></td><td>Bounds, overlap and supported shape-path checks</td></tr></tbody></table><p>A candidate column represents a selectable loading structure, not a completed final packing. Connect selection, physical placement and reporting.</p><h2 id="entry-points" tabindex="-1">Entry Points <a class="header-anchor" href="#entry-points" aria-label="Permalink to &quot;Entry Points&quot;">​</a></h2><p>Kotlin combines application requests, standard executors and a packing analyzer. Rust provides materialized/CSV paths with injected RMP and final executors. Renaming Kotlin types into snake case is not a Rust implementation.</p><p>Start with a fixed container and a small seed set, then add generators, container types and objective configuration.</p><h2 id="boundaries" tabindex="-1">Boundaries <a class="header-anchor" href="#boundaries" aria-label="Permalink to &quot;Boundaries&quot;">​</a></h2><ul><li>Cylinder support depends on axis and generation/support/final-validation paths; it does not imply arbitrary rotation in 3D.</li><li>Utilization must use the appropriate actual shape volume, not automatically its bounding cuboid.</li><li>The external renderer is separate. Producing DTOs does not launch a visualization page.</li><li>Inspect <code>finalSolved</code>, packing output and pricing diagnostics together, not just a nonempty candidate list.</li></ul><h2 id="learning-path" tabindex="-1">Learning Path <a class="header-anchor" href="#learning-path" aria-label="Permalink to &quot;Learning Path&quot;">​</a></h2><ol><li>Complete <a href="./../setup.html">environment setup</a>.</li><li>Follow <a href="./first-loading.html">your first 3D loading</a>, from candidate selection to final placements.</li><li>Add types, weight and costs, and explain the business meaning of objective weights.</li><li>See <a href="/ospf/examples/framework-example2.html">framework example 2</a> for integrated aircraft loading. Industry safety rules are not automatically included by using BPP3D.</li></ol><h2 id="reference" tabindex="-1">Reference <a class="header-anchor" href="#reference" aria-label="Permalink to &quot;Reference&quot;">​</a></h2><ul><li><a href="https://github.com/fuookami/ospf-kotlin/blob/main/ospf-kotlin-framework-bpp3d/README.md" target="_blank" rel="noreferrer">Kotlin entry points and shape paths</a></li><li><a href="https://github.com/fuookami/ospf-rust/blob/main/ospf-rust-framework-bpp3d/README.md" target="_blank" rel="noreferrer">Rust entry points and domain contracts</a></li></ul><p><a href="./../">Back to scenario selection</a></p><h2 id="continue-practicing" tabindex="-1">Continue Practicing <a class="header-anchor" href="#continue-practicing" aria-label="Permalink to &quot;Continue Practicing&quot;">​</a></h2><p>Next: <a href="./business-scenario.html">Bin Types and Objectives</a>. Before adapting the scenario to your application, complete the <a href="./../integration.html">business integration checks</a>.</p>',17)])])}const m=a(o,[["render",r]]);export{u as __pageData,m as default};
